function setup() {
	createCanvas(S=max(windowWidth, windowHeight), S);
	describe("quadtratic still of 3 rows with each 15 4-edges shifting between dark and bright")
	strokeWeight(2);
	fill(212);
	loop();
}

function draw() {
	background(32);

	const nx = 7, ny = 3;
	const xx = S / nx, yy = S / ny, dx = xx * 0.8;
	for (let y = 0; y < height; y += yy) {
		for (let x = 0; x < width; x += xx) {
			let x1 = x + noise(x, y, frameCount) * dx;
			let x2 = x + xx - noise(x+1, y, frameCount) * dx;
			let x3 = x + noise(x, y+1, frameCount) * dx;
			let x4 = x + xx - noise(x+1, y+1, frameCount) * dx;
			if (x1 > x2) [x1, x2] = [x2, x1];
			if (x3 > x4) [x3, x4] = [x4, x3];
			noStroke();
			quad(x1, y, x2, y, x4, y+yy, x3, y+yy);
			stroke(32);
			line(x1, y, x4, y + yy);
		}
	}

	// noLoop() removed for animation
}

function mouseClicked() {
	if (mouseButton != RIGHT) setup();
}
